solutions.naive:
class Solution:
    def titleToNumber(self, columnTitle: str) -> int:
        total = 0
        power = 1
        for ch in reversed(columnTitle):
            total += (ord(ch) - ord('A') + 1) * power
            power *= 26
        return total

solutions.better:
class Solution:
    def titleToNumber(self, columnTitle: str) -> int:
        value = {chr(ord('A') + i): i + 1 for i in range(26)}
        total = 0
        for ch in columnTitle:
            total = total * 26 + value[ch]
        return total

